// Normalize whatever shape the Gmail Trigger gives us into clean fields.
// Adjust field paths below if your n8n Gmail Trigger version returns a different shape
// (check the trigger's output once before relying on this).
const email = $input.item.json;

const fromHeader = email.from?.value?.[0] || {};

return {
  json: {
    sender_name: fromHeader.name || email.from?.text || 'Unknown',
    sender_email: fromHeader.address || email.from?.text || '',
    subject: email.subject || '',
    raw_email_body: email.text || email.snippet || ''
  }
};

// Combine the inserted lead (from the "Insert Lead" node) with the current
// services list (this node's input) to build the extraction prompt.
const lead = $('Insert Lead').first().json;
const services = $input.all().map(item => item.json);

const serviceList = services
  .map(s => `- ${s.name} (${s.pricing_type}, rate: ${s.rate} ${s.unit_label || ''})`)
  .join('\n');

const systemPrompt = `You are extracting requested services from a customer inquiry email for a home renovation / interiors business.

Available services:
${serviceList}

Respond ONLY with a JSON array (no prose, no markdown fences) in this exact format:
[{"service_name": "<must exactly match one of the names above>", "quantity": <number or null>, "length": <number or null>, "width": <number or null>, "notes": "<short context>"}]

If a service's pricing is per_sqft or per_sqinch, fill length and width when dimensions are mentioned. If it is per_rft (running feet), fill length only. For flat services, use quantity. If no services are clearly mentioned, respond with [].`;

return {
  json: {
    lead_id: lead.id,
    services_raw: services,
    anthropic_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 1000,
      system: systemPrompt,
      messages: [
        { role: 'user', content: lead.raw_email_body || '' }
      ]
    }
  }
};

// Parse Claude's reply, match each extracted service name to a real service,
// and keep the order Claude returned (stored as position).
const response = $input.item.json;
const leadId = $('Build AI Prompt').first().json.lead_id;
const services = $('Build AI Prompt').first().json.services_raw;

let extracted = [];
try {
  const text = response.content?.[0]?.text || '[]';
  const cleaned = text.replace(/```json|```/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = [];
}

const matched = extracted
  .map(item => ({
    item,
    match: services.find(s => s.name.toLowerCase() === (item.service_name || '').toLowerCase()),
  }))
  .filter(x => x.match);

return matched.map((x, index) => ({
  json: {
    lead_id: leadId,
    service_id: x.match.id,
    quantity: x.item.quantity ?? 1,
    length: x.item.length ?? null,
    width: x.item.width ?? null,
    notes: x.item.notes || '',
    position: index,
  },
}));
